using System;using System.Data;using System.Web;using AQOONHUB_SMS.Modules.Administration;
namespace AQOONHUB_SMS.Modules.Settings{public partial class SettingsPage:System.Web.UI.Page{readonly SystemRepository r=new SystemRepository();protected void Page_Load(object s,EventArgs e){SystemAuthorization.DemandAdmin(this);if(!IsPostBack)LoadData();}void LoadData(){DataRow x=r.SchoolSettings();if(x==null){litMessage.Text="<div class='sys-error'>School settings are unavailable.</div>";btnSave.Enabled=false;return;}txtSchool.Text=Convert.ToString(x["SchoolName"]);txtEmail.Text=Convert.ToString(x["Email"]);txtPhone.Text=Convert.ToString(x["Phone"]);txtAddress.Text=Convert.ToString(x["Address"]);Set(ddlCurrency,Convert.ToString(x["Currency"]));txtTimezone.Text=Convert.ToString(x["TimeZone"]);Set(ddlLanguage,Convert.ToString(x["Language"]));}void Set(System.Web.UI.WebControls.ListControl c,string v){if(c.Items.FindByValue(v)!=null)c.SelectedValue=v;}protected void btnReset_Click(object s,EventArgs e){LoadData();litMessage.Text="<div class='sys-note'>Values restored from saved settings.</div>";}protected void btnSave_Click(object s,EventArgs e){try{if(txtSchool.Text.Trim().Length<2)throw new Exception("School name is required.");if(!string.IsNullOrWhiteSpace(txtEmail.Text)&&!SecurityHelper.IsValidEmail(txtEmail.Text.Trim()))throw new Exception("Enter a valid school email.");r.SaveSchool(txtSchool.Text.Trim(),txtAddress.Text.Trim(),txtPhone.Text.Trim(),txtEmail.Text.Trim(),ddlCurrency.SelectedValue,txtTimezone.Text.Trim(),ddlLanguage.SelectedValue);int id;int? actor=int.TryParse(Convert.ToString(Session["UserID"]),out id)?id:(int?)null;r.Log(actor,"SETTINGS_UPDATED","Settings","Supported school settings updated",Request.UserHostAddress);litMessage.Text="<div class='sys-note' role='status'>Settings saved successfully.</div>";}catch(Exception ex){litMessage.Text="<div class='sys-error' role='alert'>"+HttpUtility.HtmlEncode(ex.Message)+"</div>";}}}}
